type Reservation struct { guests []string }

func (r *Reservation) AddGuest(guest string) error {
    if err := r.assertGuestCapacity(); err != nil {
        return err
    }
    r.guests = append(r.guests, guest)
    return nil
}

func (r *Reservation) assertGuestCapacity() error {
    if len(r.guests) >= 8 {
        return errors.New("reservation holds at most eight guests")
    }
    return nil
}
